package com.cni.evidence; import com.cni.casefile.InvestigationCase; import com.cni.user.AppUser; import jakarta.persistence.*; import lombok.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="evidence_files") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class EvidenceFile{@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="case_id",nullable=false)private InvestigationCase investigationCase;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="uploaded_by",nullable=false)private AppUser uploadedBy;@Column(nullable=false)private String originalName;@Column(nullable=false)private String storedName;private String contentType;private long sizeBytes;private String sha256;@Column(name="created_at",nullable=false)private Instant createdAt;}
